  "pitch_deck": {
    "title": "Tipperary: Transparency in Tipping",
    "tagline": "Know the norm before you dine.",
    "structure": {
      "problem_statement": {
        "headline": "The Tipping Anxiety Gap",
        "description": "Dining out in the modern economy has become a social minefield. Consumers face constant 'tipping anxiety'—the fear of either overpaying due to social pressure or underpaying and causing offense. Currently, there is no data-driven way to know what a 'fair' tip looks like at a specific establishment, leading to inconsistent service quality and customer discomfort.",
        "pain_points": [
          "Social awkwardness and decision fatigue at the end of a meal.",
          "Lack of transparency in service-based pricing models.",
          "Inconsistency in gratuity expectations across different restaurant tiers."
        ]
      },
      "solution": {
        "headline": "Data-Driven Dining Etiquette",
        "description": "Tipperary is a crowdsourced, real-time intelligence app that provides users with the average tip percentage and dollar amount for any restaurant in their vicinity.",
        "key_features": [
          "Real-time Tip Analytics: View live averages for specific venues.",
          "Smart Search: Filter restaurants by 'tip culture' (e.g., casual vs. fine dining).",
          "Seamless Integration: Scan receipts to anonymously contribute data and earn rewards.",
          "Budget Planner: Estimate total meal costs including gratuity before arriving."
        ]
      },
      "market_opportunity": {
        "target_audience": [
          "Gen Z and Millennials (the most frequent diners and tech-native users).",
          "Business travelers seeking predictable dining experiences.",
          "Tourists navigating unfamiliar local tipping customs."
        ],
        "market_size": "The global dining-out market is valued in the trillions, with a massive subset of digital-first consumers seeking transparency in service economy transactions."
      },
      "business_model": {
        "revenue_streams": [
          "Freemium Model: Basic search is free; 'Tipperary Pro' offers advanced dining insights and reservation perks.",
          "B2B Data Insights: Selling anonymized, aggregated tipping trends to restaurant groups to help them optimize staffing and service models.",
          "Affiliate Partnerships: Integrated booking fees through restaurant reservation platforms."
        ]
      },
      "competitive_advantage": {
        "differentiation": "Unlike Yelp or Google Maps, which focus on food quality and reviews, Tipperary focuses exclusively on the *financial etiquette* of the experience. We don't tell you if the food is good; we tell you how the service is valued."
      },
      "call_to_action": {
        "closing_statement": "We are eliminating the guesswork from dining. Join us in bringing transparency to the service industry.",
        "ask": "We are seeking seed funding to scale our data collection engine and launch our beta in three major metropolitan markets."
      }
    }
  }
}
